{
  "references": [
    {
      "id": "R1",
      "summary_ko": "파란 셔츠를 입은 왼쪽 남자의 치아가 부자연스러움."
    },
    {
      "id": "R2",
      "summary_ko": "왼쪽 남자의 손이 청바지 주머니 속으로 모핑됨."
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "남자가 아래를 볼 때 드레드록스 머리카락이 모핑되고 가늘어지며 부분적으로 분해됨."
    },
    {
      "id": "C2",
      "summary_ko": "파란 셔츠를 입은 남자의 손짓하는 손이 왜곡되고 주변 공기와 섞이며 구조가 변함."
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "하나는 치아 결함에 대한 설명이고 다른 하나는 머리카락 모핑에 대한 설명으로 대상과 결함이 서로 다릅니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "하나는 치아 이상을 지적하고 다른 하나는 손의 왜곡 현상을 지적하여 결함 부위가 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "하나는 손이 주머니로 모핑되는 현상이고 다른 하나는 머리카락의 변형에 관한 것이므로 대상이 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C2",
      "verdict": "uncertain",
      "reason_ko": "두 설명 모두 남자의 손 왜곡/모핑 현상을 다루고 있으나, 주머니 속으로 모핑되는 것과 손짓하는 손이 공기와 섞이며 변형되는 것이 동일한 사건인지 세부 내용상 불확실합니다."
    }
  ]
}
